CREATE FUNCTION reploom_actor() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('reploom.user_id',true),'')::uuid $$;
CREATE FUNCTION reploom_row_owner(t text, r jsonb) RETURNS uuid
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
CASE t
WHEN 'users' THEN RETURN (r->>'id')::uuid;
WHEN 'user_training_profiles' THEN RETURN (r->>'user_id')::uuid;
WHEN 'training_goals' THEN RETURN NULL::uuid;
WHEN 'metric_definitions' THEN RETURN NULL::uuid;
WHEN 'user_goals' THEN RETURN (r->>'user_id')::uuid;
WHEN 'user_equipment' THEN RETURN (r->>'user_id')::uuid;
WHEN 'user_training_days' THEN RETURN (r->>'user_id')::uuid;
WHEN 'exercises' THEN RETURN (r->>'owner_user_id')::uuid;
WHEN 'exercise_aliases' THEN RETURN public.reploom_owner('exercises',(r->>'exercise_id')::uuid);
WHEN 'muscle_groups' THEN RETURN NULL::uuid;
WHEN 'exercise_muscles' THEN RETURN public.reploom_owner('exercises',(r->>'exercise_id')::uuid);
WHEN 'equipment' THEN RETURN NULL::uuid;
WHEN 'exercise_equipment' THEN RETURN public.reploom_owner('exercises',(r->>'exercise_id')::uuid);
WHEN 'exercise_alternatives' THEN RETURN public.reploom_owner('exercises',(r->>'exercise_id')::uuid);
WHEN 'media_files' THEN RETURN (r->>'owner_user_id')::uuid;
WHEN 'exercise_media' THEN RETURN public.reploom_owner('exercises',(r->>'exercise_id')::uuid);
WHEN 'workout_templates' THEN RETURN (r->>'owner_user_id')::uuid;
WHEN 'workout_template_versions' THEN RETURN public.reploom_owner('workout_templates',(r->>'template_id')::uuid);
WHEN 'template_exercise_groups' THEN RETURN public.reploom_owner('workout_template_versions',(r->>'template_version_id')::uuid);
WHEN 'template_exercises' THEN RETURN public.reploom_owner('workout_template_versions',(r->>'template_version_id')::uuid);
WHEN 'template_sets' THEN RETURN public.reploom_owner('template_exercises',(r->>'template_exercise_id')::uuid);
WHEN 'template_set_segments' THEN RETURN public.reploom_owner('template_sets',(r->>'template_set_id')::uuid);
WHEN 'training_programs' THEN RETURN (r->>'owner_user_id')::uuid;
WHEN 'training_program_versions' THEN RETURN public.reploom_owner('training_programs',(r->>'program_id')::uuid);
WHEN 'program_goals' THEN RETURN public.reploom_owner('training_program_versions',(r->>'program_version_id')::uuid);
WHEN 'program_blocks' THEN RETURN public.reploom_owner('training_program_versions',(r->>'program_version_id')::uuid);
WHEN 'program_weeks' THEN RETURN public.reploom_owner('program_blocks',(r->>'program_block_id')::uuid);
WHEN 'planned_workouts' THEN RETURN public.reploom_owner('program_weeks',(r->>'program_week_id')::uuid);
WHEN 'planned_exercise_groups' THEN RETURN public.reploom_owner('planned_workouts',(r->>'planned_workout_id')::uuid);
WHEN 'planned_workout_exercises' THEN RETURN public.reploom_owner('planned_workouts',(r->>'planned_workout_id')::uuid);
WHEN 'planned_workout_sets' THEN RETURN public.reploom_owner('planned_workout_exercises',(r->>'planned_exercise_id')::uuid);
WHEN 'planned_set_segments' THEN RETURN public.reploom_owner('planned_workout_sets',(r->>'planned_set_id')::uuid);
WHEN 'program_runs' THEN RETURN (r->>'user_id')::uuid;
WHEN 'scheduled_workouts' THEN RETURN public.reploom_owner('program_runs',(r->>'program_run_id')::uuid);
WHEN 'schedule_changes' THEN RETURN public.reploom_owner('scheduled_workouts',(r->>'scheduled_workout_id')::uuid);
WHEN 'progression_policies' THEN RETURN public.reploom_owner('training_program_versions',(r->>'program_version_id')::uuid);
WHEN 'workout_adjustments' THEN RETURN public.reploom_owner('scheduled_workouts',(r->>'scheduled_workout_id')::uuid);
WHEN 'workout_sessions' THEN RETURN (r->>'user_id')::uuid;
WHEN 'session_exercise_groups' THEN RETURN public.reploom_owner('workout_sessions',(r->>'session_id')::uuid);
WHEN 'session_exercises' THEN RETURN public.reploom_owner('workout_sessions',(r->>'session_id')::uuid);
WHEN 'session_sets' THEN RETURN public.reploom_owner('session_exercises',(r->>'session_exercise_id')::uuid);
WHEN 'session_set_segments' THEN RETURN public.reploom_owner('session_sets',(r->>'session_set_id')::uuid);
WHEN 'session_pauses' THEN RETURN public.reploom_owner('workout_sessions',(r->>'session_id')::uuid);
WHEN 'rest_intervals' THEN RETURN public.reploom_owner('workout_sessions',(r->>'session_id')::uuid);
WHEN 'session_media' THEN RETURN public.reploom_owner('workout_sessions',(r->>'session_id')::uuid);
WHEN 'session_revisions' THEN RETURN public.reploom_owner('workout_sessions',(r->>'session_id')::uuid);
WHEN 'body_measurements' THEN RETURN (r->>'user_id')::uuid;
WHEN 'recovery_checkins' THEN RETURN (r->>'user_id')::uuid;
WHEN 'muscle_soreness' THEN RETURN public.reploom_owner('recovery_checkins',(r->>'checkin_id')::uuid);
WHEN 'movement_discomforts' THEN RETURN public.reploom_owner('recovery_checkins',(r->>'checkin_id')::uuid);
WHEN 'personal_records' THEN RETURN (r->>'user_id')::uuid;
WHEN 'analytics_snapshots' THEN RETURN (r->>'user_id')::uuid;
WHEN 'foods' THEN RETURN (r->>'owner_user_id')::uuid;
WHEN 'meal_entries' THEN RETURN (r->>'user_id')::uuid;
WHEN 'meal_items' THEN RETURN public.reploom_owner('meal_entries',(r->>'meal_entry_id')::uuid);
WHEN 'water_entries' THEN RETURN (r->>'user_id')::uuid;
WHEN 'nutrition_targets' THEN RETURN (r->>'user_id')::uuid;
WHEN 'hydration_targets' THEN RETURN (r->>'user_id')::uuid;
WHEN 'food_recognitions' THEN RETURN (r->>'user_id')::uuid;
WHEN 'food_recognition_items' THEN RETURN public.reploom_owner('food_recognitions',(r->>'recognition_id')::uuid);
WHEN 'user_consents' THEN RETURN (r->>'user_id')::uuid;
WHEN 'ai_analysis_requests' THEN RETURN (r->>'user_id')::uuid;
WHEN 'ai_recommendations' THEN RETURN public.reploom_owner('ai_analysis_requests',(r->>'analysis_request_id')::uuid);
WHEN 'ai_decisions' THEN RETURN public.reploom_owner('ai_recommendations',(r->>'recommendation_id')::uuid);
WHEN 'recommendation_applications' THEN RETURN public.reploom_owner('ai_recommendations',(r->>'recommendation_id')::uuid);
WHEN 'sync_operations' THEN RETURN (r->>'user_id')::uuid;
WHEN 'export_jobs' THEN RETURN (r->>'user_id')::uuid;
ELSE RAISE EXCEPTION 'Unknown domain table %',t; END CASE; END $$;
CREATE FUNCTION reploom_owner(t text, row_id uuid) RETURNS uuid
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE r jsonb;
BEGIN
IF row_id IS NULL THEN RETURN NULL; END IF;
IF t NOT IN ('users','user_training_profiles','training_goals','metric_definitions','user_goals','user_equipment','user_training_days','exercises','exercise_aliases','muscle_groups','exercise_muscles','equipment','exercise_equipment','exercise_alternatives','media_files','exercise_media','workout_templates','workout_template_versions','template_exercise_groups','template_exercises','template_sets','template_set_segments','training_programs','training_program_versions','program_goals','program_blocks','program_weeks','planned_workouts','planned_exercise_groups','planned_workout_exercises','planned_workout_sets','planned_set_segments','program_runs','scheduled_workouts','schedule_changes','progression_policies','workout_adjustments','workout_sessions','session_exercise_groups','session_exercises','session_sets','session_set_segments','session_pauses','rest_intervals','session_media','session_revisions','body_measurements','recovery_checkins','muscle_soreness','movement_discomforts','personal_records','analytics_snapshots','foods','meal_entries','meal_items','water_entries','nutrition_targets','hydration_targets','food_recognitions','food_recognition_items','user_consents','ai_analysis_requests','ai_recommendations','ai_decisions','recommendation_applications','sync_operations','export_jobs') THEN RAISE EXCEPTION 'Unknown domain table'; END IF;
EXECUTE format('SELECT to_jsonb(x) FROM public.%I x WHERE id=$1',t) INTO r USING row_id;
IF r IS NULL THEN RAISE EXCEPTION 'Referenced % % does not exist',t,row_id USING ERRCODE='23503'; END IF;
RETURN public.reploom_row_owner(t,r);
END $$;

CREATE FUNCTION reploom_guard_ownership() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE r jsonb:=to_jsonb(NEW); oldr jsonb:=to_jsonb(OLD); o uuid; p uuid; f text; target text;
BEGIN
IF TG_OP='UPDATE' AND NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'Identity is immutable' USING ERRCODE='23514'; END IF;
IF TG_OP='UPDATE' AND TG_ARGV[0]<>'' AND r->TG_ARGV[0] IS DISTINCT FROM oldr->TG_ARGV[0] THEN
 RAISE EXCEPTION 'Aggregate ownership path is immutable' USING ERRCODE='23514'; END IF;
o:=reploom_row_owner(TG_TABLE_NAME,r);
FOR f,target IN SELECT key,value FROM jsonb_each_text(TG_ARGV[1]::jsonb) LOOP
 IF r->>f IS NOT NULL THEN
  p:=reploom_owner(target,(r->>f)::uuid);
  IF p IS NOT NULL AND p IS DISTINCT FROM o THEN RAISE EXCEPTION 'Cross-owner reference %.%',TG_TABLE_NAME,f USING ERRCODE='23514'; END IF;
 END IF;
END LOOP;
RETURN NEW;
END $$;

