DO $$ BEGIN
IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='reploom_app') THEN CREATE ROLE reploom_app NOLOGIN NOSUPERUSER NOBYPASSRLS; END IF;
END $$;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO reploom_app;

ALTER TABLE users ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own ON users FOR SELECT TO reploom_app USING (reploom_actor() IS NOT NULL AND ((reploom_owner('users',id) IS NULL OR reploom_owner('users',id)=reploom_actor())));
CREATE POLICY insert_own ON users FOR INSERT TO reploom_app WITH CHECK (reploom_row_owner('users',to_jsonb(users))=reploom_actor());
CREATE POLICY update_own ON users FOR UPDATE TO reploom_app USING (reploom_owner('users',id)=reploom_actor()) WITH CHECK (reploom_row_owner('users',to_jsonb(users))=reploom_actor());
CREATE POLICY delete_own ON users FOR DELETE TO reploom_app USING (reploom_owner('users',id)=reploom_actor());
GRANT SELECT,INSERT,UPDATE,DELETE ON users TO reploom_app;
