CREATE POLICY read_own ON user_consents FOR SELECT TO reploom_app USING (reploom_actor() IS NOT NULL AND ((reploom_owner('user_consents',id) IS NULL OR reploom_owner('user_consents',id)=reploom_actor())));
CREATE POLICY insert_own ON user_consents FOR INSERT TO reploom_app WITH CHECK (reploom_row_owner('user_consents',to_jsonb(user_consents))=reploom_actor());
CREATE POLICY update_own ON user_consents FOR UPDATE TO reploom_app USING (reploom_owner('user_consents',id)=reploom_actor()) WITH CHECK (reploom_row_owner('user_consents',to_jsonb(user_consents))=reploom_actor());
CREATE POLICY delete_own ON user_consents FOR DELETE TO reploom_app USING (reploom_owner('user_consents',id)=reploom_actor());
GRANT SELECT,INSERT,UPDATE,DELETE ON user_consents TO reploom_app;
